<?php

declare(strict_types=1);

namespace Modules\Platform\OpenApi;

use OpenApi\Attributes as OA;

/**
 * OpenAPI operations of the sign-in side of the identity routes: the two-factor challenge and TOTP enrolment, the SSO
 * redirect and callback, the sessions of the signed-in user and the impersonation of a user by an administrator. The
 * payloads are described by the FormRequest or the validation of each controller action.
 */
#[OA\Post(path: '/api/v1/auth/2fa/challenge', operationId: 'verifyTwoFactorChallenge', summary: 'Complete a sign-in with the second factor', tags: ['Identity'], responses: [new OA\Response(response: 200, description: 'Signed in', content: new OA\JsonContent(ref: '#/components/schemas/ApiSuccessResponse')), new OA\Response(response: 422, description: 'Invalid code', content: new OA\JsonContent(ref: '#/components/schemas/ApiValidationErrorResponse')), new OA\Response(response: 429, description: 'Too many attempts')])]
#[OA\Get(path: '/api/v1/auth/sso/{provider}/redirect', operationId: 'redirectToSsoProvider', summary: 'Start a single sign-on with a provider', parameters: [new OA\Parameter(name: 'provider', in: 'path', required: true, schema: new OA\Schema(type: 'string'))], tags: ['Identity'], responses: [new OA\Response(response: 302, description: 'Redirect to the identity provider'), new OA\Response(response: 404, description: 'Unknown provider', content: new OA\JsonContent(ref: '#/components/schemas/ApiErrorResponse'))])]
#[OA\Get(path: '/api/v1/auth/sso/{provider}/callback', operationId: 'handleSsoProviderCallback', summary: 'Single sign-on callback of a provider', parameters: [new OA\Parameter(name: 'provider', in: 'path', required: true, schema: new OA\Schema(type: 'string'))], tags: ['Identity'], responses: [new OA\Response(response: 200, description: 'Signed in', content: new OA\JsonContent(ref: '#/components/schemas/ApiSuccessResponse')), new OA\Response(response: 422, description: 'Rejected assertion', content: new OA\JsonContent(ref: '#/components/schemas/ApiValidationErrorResponse'))])]
#[OA\Post(path: '/api/v1/auth/sso/{provider}/callback', operationId: 'postSsoProviderCallback', summary: 'Single sign-on callback of a provider (form post binding)', requestBody: new OA\RequestBody(required: false, content: new OA\JsonContent(type: 'object')), parameters: [new OA\Parameter(name: 'provider', in: 'path', required: true, schema: new OA\Schema(type: 'string'))], tags: ['Identity'], responses: [new OA\Response(response: 200, description: 'Signed in', content: new OA\JsonContent(ref: '#/components/schemas/ApiSuccessResponse')), new OA\Response(response: 422, description: 'Rejected assertion', content: new OA\JsonContent(ref: '#/components/schemas/ApiValidationErrorResponse'))])]
#[OA\Post(path: '/api/v1/auth/2fa/totp', operationId: 'enableTotpTwoFactor', summary: 'Start the enrolment of an authenticator app', security: [['bearerAuth' => []]], requestBody: new OA\RequestBody(required: false, content: new OA\JsonContent(type: 'object')), tags: ['Identity'], responses: [new OA\Response(response: 200, description: 'Secret and provisioning URI', content: new OA\JsonContent(ref: '#/components/schemas/ApiSuccessResponse')), new OA\Response(response: 422, description: 'Validation error', content: new OA\JsonContent(ref: '#/components/schemas/ApiValidationErrorResponse'))])]
#[OA\Post(path: '/api/v1/auth/2fa/totp/confirm', operationId: 'confirmTotpTwoFactor', summary: 'Confirm the authenticator app with a code', security: [['bearerAuth' => []]], requestBody: new OA\RequestBody(required: true, content: new OA\JsonContent(type: 'object')), tags: ['Identity'], responses: [new OA\Response(response: 200, description: 'Two-factor enabled', content: new OA\JsonContent(ref: '#/components/schemas/ApiSuccessResponse')), new OA\Response(response: 422, description: 'Invalid code', content: new OA\JsonContent(ref: '#/components/schemas/ApiValidationErrorResponse'))])]
#[OA\Delete(path: '/api/v1/auth/2fa/totp', operationId: 'disableTotpTwoFactor', summary: 'Disable the authenticator app', security: [['bearerAuth' => []]], tags: ['Identity'], responses: [new OA\Response(response: 200, description: 'Two-factor disabled', content: new OA\JsonContent(ref: '#/components/schemas/ApiSuccessResponse')), new OA\Response(response: 422, description: 'Validation error', content: new OA\JsonContent(ref: '#/components/schemas/ApiValidationErrorResponse'))])]
#[OA\Get(path: '/api/v1/profile/sessions', operationId: 'listOwnSessions', summary: 'Active sessions of the signed-in user', security: [['bearerAuth' => []]], tags: ['Identity'], responses: [new OA\Response(response: 200, description: 'The sessions', content: new OA\JsonContent(ref: '#/components/schemas/ApiSuccessResponse'))])]
#[OA\Delete(path: '/api/v1/profile/sessions/{id}', operationId: 'revokeOwnSession', summary: 'Sign out one of the own sessions', security: [['bearerAuth' => []]], parameters: [new OA\Parameter(name: 'id', in: 'path', required: true, schema: new OA\Schema(type: 'string'))], tags: ['Identity'], responses: [new OA\Response(response: 200, description: 'Session revoked', content: new OA\JsonContent(ref: '#/components/schemas/ApiSuccessResponse')), new OA\Response(response: 404, description: 'Unknown session', content: new OA\JsonContent(ref: '#/components/schemas/ApiErrorResponse'))])]
#[OA\Post(path: '/api/v1/settings/users/{user}/impersonate', operationId: 'startUserImpersonation', summary: 'Act as a user of the tenant (audited)', security: [['bearerAuth' => []]], requestBody: new OA\RequestBody(required: false, content: new OA\JsonContent(type: 'object')), parameters: [new OA\Parameter(name: 'user', in: 'path', required: true, schema: new OA\Schema(type: 'string', format: 'uuid'))], tags: ['Identity'], responses: [new OA\Response(response: 200, description: 'Impersonation started', content: new OA\JsonContent(ref: '#/components/schemas/ApiSuccessResponse')), new OA\Response(response: 403, description: 'Not allowed', content: new OA\JsonContent(ref: '#/components/schemas/ApiErrorResponse')), new OA\Response(response: 422, description: 'Validation error', content: new OA\JsonContent(ref: '#/components/schemas/ApiValidationErrorResponse'))])]
#[OA\Delete(path: '/api/v1/settings/users/{user}/impersonate', operationId: 'endUserImpersonation', summary: 'Stop acting as a user', security: [['bearerAuth' => []]], parameters: [new OA\Parameter(name: 'user', in: 'path', required: true, schema: new OA\Schema(type: 'string', format: 'uuid'))], tags: ['Identity'], responses: [new OA\Response(response: 200, description: 'Impersonation ended', content: new OA\JsonContent(ref: '#/components/schemas/ApiSuccessResponse')), new OA\Response(response: 403, description: 'Not allowed', content: new OA\JsonContent(ref: '#/components/schemas/ApiErrorResponse'))])]
#[OA\Get(path: '/api/v1/settings/access-review', operationId: 'getAccessReview', summary: 'Periodic access review of the users and their roles', security: [['bearerAuth' => []]], tags: ['Identity'], responses: [new OA\Response(response: 200, description: 'The review', content: new OA\JsonContent(ref: '#/components/schemas/ApiSuccessResponse')), new OA\Response(response: 403, description: 'Not allowed', content: new OA\JsonContent(ref: '#/components/schemas/ApiErrorResponse'))])]
final class IdentityAccessOpenApi {}
